```gdscript
extends SceneTree

enum Posture { SHUT, AJAR, WIDE }

var transitions := {
	Posture.SHUT: [Posture.AJAR],
	Posture.AJAR: [Posture.WIDE],
	Posture.WIDE: [Posture.SHUT]
}

func can_move(from: int, to: int) -> bool:
	if not transitions.has(from):
		return false
	return to in transitions[from]

func _init():
	assert(can_move(Posture.SHUT, Posture.AJAR), "SHUT -> AJAR should be legal")
	assert(not can_move(Posture.AJAR, Posture.SHUT), "AJAR -> SHUT should be illegal")
	print("transitions verified for Posture")
	quit()
```

