	Condition.HIDDEN: [Condition.REVEALED],
	Condition.REVEALED: [Condition.CLAIMED],
	Condition.CLAIMED: [Condition.HIDDEN]
}

func can_move(from: int, to: int) -> bool:
	if not transitions.has(from):
		return false
	return to in transitions[from]

func _init():
	assert(can_move(Condition.HIDDEN, Condition.REVEALED), "HIDDEN -> REVEALED should be legal")
	assert(not can_move(Condition.REVEALED, Condition.HIDDEN), "REVEALED -> HIDDEN should be illegal")
	print("transitions verified for Condition")
	quit()
```

